import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.B0p3fmqd.js";const u=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1791036569000}'),i={name:"guide/index.md"};function s(n,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Welcome to the Filthy Lytiez documentation. Every script here is built to run on any server, so there is nothing framework specific to set up.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><p>Every script needs the same three resources running before it starts.</p><table tabindex="0"><thead><tr><th>Resource</th><th>Why</th></tr></thead><tbody><tr><td><a href="/script-documentation/guide/community-bridge">community_bridge</a></td><td>Detects your framework, inventory, target, notify and fuel system</td></tr><tr><td><code>ox_lib</code></td><td>UI helpers</td></tr><tr><td><code>oxmysql</code></td><td>Database. Each script creates its own tables on first start</td></tr></tbody></table><h2 id="installing-a-script" tabindex="-1">Installing a script <a class="header-anchor" href="#installing-a-script" aria-label="Permalink to &quot;Installing a script&quot;">​</a></h2><ol><li>Drop the folder into your resources.</li><li>Add <code>ensure &lt;script name&gt;</code> to your server cfg, after the three resources above.</li><li>Add the script&#39;s permission to your permissions cfg.</li><li>Add any inventory items the script lists on its installation page.</li><li>Restart the server.</li></ol><p>There is no SQL file to import for any script.</p><h2 id="editing-after-purchase" tabindex="-1">Editing after purchase <a class="header-anchor" href="#editing-after-purchase" aria-label="Permalink to &quot;Editing after purchase&quot;">​</a></h2><p>Each script leaves its config files open so you can edit them. The rest of the resource is protected, and edits to protected files are lost on update. The files you can edit are listed on each script&#39;s configuration page.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><p>Every script prints one line at startup telling you whether you are on the latest release. Set <code>Config.CheckForUpdates = false</code> to silence it. Nothing is uploaded and nothing is downloaded either way.</p><h2 id="need-help" tabindex="-1">Need help? <a class="header-anchor" href="#need-help" aria-label="Permalink to &quot;Need help?&quot;">​</a></h2><p>Start with <a href="/script-documentation/troubleshooting/common-issues">Common issues</a>, then the <a href="/script-documentation/troubleshooting/faq">FAQ</a>. If you are still stuck, see <a href="/script-documentation/troubleshooting/support">Support</a>.</p>',14)])])}const f=t(i,[["render",s]]);export{u as __pageData,f as default};
